            tools.Add(Management("garrison_create_change_rule", ResourceTypeEnum.ChangeRule, OperationTypeEnum.Create,
                "Create a change rule that lets executives apply narrow classes of change inside a unit's subtree without waiting for you. Required: organization, unit (the rule covers it and every unit below it), name, classes (PromptRetune, WakeTuning, MandateTextEdit, AddWorker, RemoveWorker, ModelChange, DeploymentWeight). Optional: description, active (default true), expiresUtc, limits (class, name, minimum, maximum), for example WakeTuning minIntervalSeconds 300 to 3600, or AddWorker count at most 1, and gateEvalSet with gateThreshold (default 1): an approved eval set an AddWorker or ModelChange change must pass, in an eval run of the draft made after its last change, before the rule covers it. Only people create rules. Requires ChangeRule.Create permission.",
                "{\"type\":\"object\",\"properties\":{\"organization\":{\"type\":\"string\"},\"unit\":{\"type\":\"string\"},\"name\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":128},\"description\":{\"type\":\"string\",\"maxLength\":2000},\"active\":{\"type\":\"boolean\"},\"expiresUtc\":{\"type\":\"string\",\"description\":\"ISO 8601 UTC; omit for no expiry.\"},\"classes\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"enum\":[\"PromptRetune\",\"WakeTuning\",\"MandateTextEdit\",\"AddWorker\",\"RemoveWorker\",\"ModelChange\",\"DeploymentWeight\"]},\"minItems\":1},\"limits\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"class\":{\"type\":\"string\",\"enum\":[\"PromptRetune\",\"WakeTuning\",\"MandateTextEdit\",\"AddWorker\",\"RemoveWorker\",\"ModelChange\",\"DeploymentWeight\"]},\"name\":{\"type\":\"string\",\"description\":\"count (any class), minIntervalSeconds, maxIntervalSeconds, backoffFactor, jitterPercent (WakeTuning), or weight (DeploymentWeight).\"},\"minimum\":{\"type\":\"number\",\"minimum\":0},\"maximum\":{\"type\":\"number\",\"minimum\":0}},\"required\":[\"class\",\"name\"]}},\"gateEvalSet\":{\"type\":\"string\",\"maxLength\":128,\"description\":\"Approved eval set that AddWorker and ModelChange changes must pass.\"},\"gateThreshold\":{\"type\":\"number\",\"minimum\":0,\"maximum\":1}},\"required\":[\"organization\",\"unit\",\"name\",\"classes\"]}"));
            tools.Add(Management("garrison_update_change_rule", ResourceTypeEnum.ChangeRule, OperationTypeEnum.Update,
                "Change a change rule. Required: ruleId. Optional: unit, name, description, active, expiresUtc, classes, limits, gateEvalSet (an empty string removes the gate), gateThreshold; fields you leave out keep their values, and classes or limits you pass replace the lists. A rule stays with its organization. Requires ChangeRule.Update permission.",
                "{\"type\":\"object\",\"properties\":{\"ruleId\":{\"type\":\"string\"},\"unit\":{\"type\":\"string\"},\"name\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":128},\"description\":{\"type\":\"string\",\"maxLength\":2000},\"active\":{\"type\":\"boolean\"},\"expiresUtc\":{\"type\":\"string\",\"description\":\"ISO 8601 UTC; omit for no expiry.\"},\"classes\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"enum\":[\"PromptRetune\",\"WakeTuning\",\"MandateTextEdit\",\"AddWorker\",\"RemoveWorker\",\"ModelChange\",\"DeploymentWeight\"]},\"minItems\":1},\"limits\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"class\":{\"type\":\"string\",\"enum\":[\"PromptRetune\",\"WakeTuning\",\"MandateTextEdit\",\"AddWorker\",\"RemoveWorker\",\"ModelChange\",\"DeploymentWeight\"]},\"name\":{\"type\":\"string\",\"description\":\"count (any class), minIntervalSeconds, maxIntervalSeconds, backoffFactor, jitterPercent (WakeTuning), or weight (DeploymentWeight).\"},\"minimum\":{\"type\":\"number\",\"minimum\":0},\"maximum\":{\"type\":\"number\",\"minimum\":0}},\"required\":[\"class\",\"name\"]}},\"gateEvalSet\":{\"type\":\"string\",\"maxLength\":128,\"description\":\"Approved eval set that AddWorker and ModelChange changes must pass.\"},\"gateThreshold\":{\"type\":\"number\",\"minimum\":0,\"maximum\":1}},\"required\":[\"ruleId\"]}"));
