            tools.Add(Management("garrison_list_canary_releases", ResourceTypeEnum.CanaryRelease, OperationTypeEnum.Read,
                "List canary releases, newest first, with their current step, status (Running, Promoted, RolledBack, Aborted), and rollback reason. Optional: agent (identifier), status, skip, maxResults. Requires CanaryRelease.Read permission.",
                "{\"type\":\"object\",\"properties\":{\"agent\":{\"type\":\"string\"},\"status\":{\"type\":\"string\",\"enum\":[\"Running\",\"Promoted\",\"RolledBack\",\"Aborted\"]},\"skip\":{\"type\":\"integer\",\"minimum\":0},\"maxResults\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":100}}}"));
            tools.Add(Management("garrison_get_canary_release", ResourceTypeEnum.CanaryRelease, OperationTypeEnum.Read,
