            tools.Add(Management("garrison_start_canary", ResourceTypeEnum.CanaryRelease, OperationTypeEnum.Create,
                "Start a canary release that moves an agent's traffic from a baseline deployment to a candidate in steps. Each step gives the candidate weightPercent of the traffic (deployment weight percent times 10, the baseline the rest) and advances once it has minimumRuns finished runs and minimumMinutes have passed, while the candidate's error rate stays at or below maxErrorRatePercent and, with an eval gate, its latest eval score on evalSetId is at least minEvalScore. Past the last step (weightPercent 100) the candidate is promoted; a crossed threshold rolls both weights back and notifies CanaryRolledBack. Required: agent, candidateDeployment, baselineDeployment, steps (weightPercent rising to 100). Optional: maxErrorRatePercent (default 5), minEvalScore with evalSetId. Requires CanaryRelease.Create and Deployment.Update permission.",
                "{\"type\":\"object\",\"properties\":{\"agent\":{\"type\":\"string\"},\"candidateDeployment\":{\"type\":\"string\"},\"baselineDeployment\":{\"type\":\"string\"},\"steps\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":20,\"items\":{\"type\":\"object\",\"properties\":{\"weightPercent\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":100},\"minimumRuns\":{\"type\":\"integer\",\"minimum\":0},\"minimumMinutes\":{\"type\":\"integer\",\"minimum\":0}},\"required\":[\"weightPercent\"]}},\"maxErrorRatePercent\":{\"type\":\"number\",\"minimum\":0,\"maximum\":100},\"minEvalScore\":{\"type\":\"number\",\"minimum\":0,\"maximum\":1},\"evalSetId\":{\"type\":\"string\"}},\"required\":[\"agent\",\"candidateDeployment\",\"baselineDeployment\",\"steps\"]}"));
            tools.Add(Management("garrison_abort_canary", ResourceTypeEnum.CanaryRelease, OperationTypeEnum.Update,
