            // AA9.12: eval tools. Executive runs run sets against their own drafts and read their own eval runs.
            tools.Add(Tool("garrison_run_eval", ResourceTypeEnum.EvalRun, OperationTypeEnum.Execute,
                "Run an eval set and get back an eval run to follow with garrison_get_eval_run. Each case runs as its own run and is scored by its checks (ExactMatch, Contains, JsonSchemaValid, Judge); the run's score is the weighted mean, and it passes when the score reaches threshold. Required: set (identifier or name; a name runs its latest approved version unless setVersion is given). An executive run evaluates its own studio draft: pass studioDraftId and optionally agent (default: the draft's entry agent); hidden cases come back as scores only. People may instead pass agent with optional agentRevisionId, or deployment, and inputMode RecentInputs with recentInputCount to replay a deployment's recent inputs. Optional: threshold (0 to 1), budgetUsd (stops starting cases once spent). People need EvalRun.Execute and Execute on the agent.",
                "{\"type\":\"object\",\"properties\":{\"set\":{\"type\":\"string\"},\"setVersion\":{\"type\":\"integer\",\"minimum\":1},\"studioDraftId\":{\"type\":\"string\"},\"agent\":{\"type\":\"string\"},\"agentRevisionId\":{\"type\":\"string\",\"description\":\"People only.\"},\"deployment\":{\"type\":\"string\",\"description\":\"People only.\"},\"inputMode\":{\"type\":\"string\",\"enum\":[\"Cases\",\"RecentInputs\"],\"description\":\"People only; RecentInputs needs deployment.\"},\"recentInputCount\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":1000},\"threshold\":{\"type\":\"number\",\"minimum\":0,\"maximum\":1},\"budgetUsd\":{\"type\":\"number\",\"minimum\":0,\"maximum\":100000}},\"required\":[\"set\"]}"));
            tools.Add(Tool("garrison_get_eval_run", ResourceTypeEnum.EvalRun, OperationTypeEnum.Read,
                "Read an eval run: its status (Pending, Running, Completed, Failed, Cancelled), score, threshold, passed, counts, cost, and failure reason, with each case's result (output, per-check scores and notes) unless includeResults is false. An executive run reads only the eval runs its own agent started, and hidden cases come back as scores only. Required: evalRunId. People need EvalRun.Read.",
                "{\"type\":\"object\",\"properties\":{\"evalRunId\":{\"type\":\"string\"},\"includeResults\":{\"type\":\"boolean\"}},\"required\":[\"evalRunId\"]}"));
            tools.Add(Management("garrison_list_eval_sets", ResourceTypeEnum.EvalSet, OperationTypeEnum.Read,
                "List eval set versions, newest first, with state (Draft, Approved), origin (Human, Evaluator, Playground), approver, judge agent, and case count. Optional: state, origin, tag, latestOnly (only the newest version of each set), search (part of a name), skip, maxResults (1 to 100, default 25). Requires EvalSet.Read permission.",
                "{\"type\":\"object\",\"properties\":{\"state\":{\"type\":\"string\",\"enum\":[\"Draft\",\"Approved\"]},\"origin\":{\"type\":\"string\",\"enum\":[\"Human\",\"Evaluator\",\"Playground\"]},\"tag\":{\"type\":\"string\"},\"latestOnly\":{\"type\":\"boolean\"},\"search\":{\"type\":\"string\"},\"skip\":{\"type\":\"integer\",\"minimum\":0},\"maxResults\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":100}}}"));
            tools.Add(Management("garrison_create_eval_set", ResourceTypeEnum.EvalSet, OperationTypeEnum.Create,
                "Create version 1 of an eval set as a draft. Required: name. Optional: description, origin (Human or Playground), judgeAgent (the agent that grades Judge checks and cases without expected text), tags, and cases: each with inputText (required), name, expectedText, hidden (hidden cases are never shown to the agents being evaluated), and checks (scorer ExactMatch, Contains, JsonSchemaValid, or Judge; argument: the expected text, substring, JSON Schema, or grading criteria; weight 0 to 100, default 1). A set gates promotions only after a person approves it. Requires EvalSet.Create permission.",
                "{\"type\":\"object\",\"properties\":{\"name\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":128},\"description\":{\"type\":\"string\",\"maxLength\":2000},\"origin\":{\"type\":\"string\",\"enum\":[\"Human\",\"Playground\"]},\"judgeAgent\":{\"type\":\"string\"},\"tags\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"maxLength\":64}},\"cases\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"name\":{\"type\":\"string\"},\"inputText\":{\"type\":\"string\"},\"expectedText\":{\"type\":\"string\"},\"hidden\":{\"type\":\"boolean\"},\"checks\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"scorer\":{\"type\":\"string\",\"enum\":[\"ExactMatch\",\"Contains\",\"JsonSchemaValid\",\"Judge\"]},\"argument\":{\"type\":\"string\"},\"weight\":{\"type\":\"number\",\"minimum\":0,\"maximum\":100}},\"required\":[\"scorer\"]}}},\"required\":[\"inputText\"]}}},\"required\":[\"name\"]}"));
            tools.Add(Management("garrison_approve_eval_set", ResourceTypeEnum.EvalSet, OperationTypeEnum.Update,
                "Approve a draft eval set version so it can gate promotions and executive changes. An approved version never changes; editing it makes its next version. Only people approve. Required: set (identifier of the version, or a name for its newest version). Requires EvalSet.Update permission.",
                "{\"type\":\"object\",\"properties\":{\"set\":{\"type\":\"string\"}},\"required\":[\"set\"]}"));
            return tools;
        }

        #endregion

        #region Private-Methods

        private static McpToolDefinition Management(string name, ResourceTypeEnum resourceType, OperationTypeEnum operation, string description, string schema)
        {
            McpToolDefinition tool = Tool(name, resourceType, operation, description, schema);
            tool.ManagementTool = true;
            tool.UserOnly = true;
            return tool;
        }

        private static McpToolDefinition UserTool(string name, ResourceTypeEnum resourceType, OperationTypeEnum operation, string description, string schema)
        {
            McpToolDefinition tool = Tool(name, resourceType, operation, description, schema);
            tool.UserOnly = true;
            return tool;
        }

        private static string RevisionSchema()
        {
            Dictionary<string, object?> properties = new Dictionary<string, object?>();
            properties["mandate"] = new Dictionary<string, object?> { ["type"] = "string", ["description"] = "Mandate name or identifier (mdt_...)." };
            properties["revision"] = OpenApiSchemaFactory.For(typeof(MandateRevision));
            return Serializer.Serialize(new Dictionary<string, object?> { ["type"] = "object", ["properties"] = properties, ["required"] = new List<string> { "mandate", "revision" } });
        }

        private static string ConfigurationSchema(Type type, string? identifier)
        {
            Dictionary<string, object?> properties = new Dictionary<string, object?>();
            properties["configuration"] = OpenApiSchemaFactory.For(type);
            List<string> required = new List<string> { "configuration" };
            if (identifier != null)
            {
                properties[identifier] = new Dictionary<string, object?> { ["type"] = "string" };
                required.Add(identifier);
            }
            return Serializer.Serialize(new Dictionary<string, object?> { ["type"] = "object", ["properties"] = properties, ["required"] = required });
        }

        private static McpToolDefinition Tool(string name, ResourceTypeEnum resourceType, OperationTypeEnum operation, string description, string schema)
        {
            McpToolDefinition tool = new McpToolDefinition();
            tool.Name = name;
            tool.ResourceType = resourceType;
            tool.Operation = operation;
            tool.Annotations = new Garrison.Core.Models.EffectToolMetadata
            {
                ReadOnlyHint = operation == OperationTypeEnum.Read,
                IdempotentHint = operation == OperationTypeEnum.Read ? true : null,
                DestructiveHint = operation == OperationTypeEnum.Read ? false : null
            };
            tool.DescriptionTemplate = BuiltInDescriptionPrefix + name;
            tool.DefaultDescription = description;
            tool.InputSchemaJson = schema;
            tool.AdministratorInputSchemaJson = WithTenantId(schema);
            return tool;
        }

        private static string WithTenantId(string schema)
        {
            Dictionary<string, object?> document = Serializer.Deserialize<Dictionary<string, object?>>(schema) ?? new Dictionary<string, object?>();
            Dictionary<string, object?> properties = document.TryGetValue("properties", out object? value)
                ? Serializer.Deserialize<Dictionary<string, object?>>(Serializer.Serialize(value)) ?? new Dictionary<string, object?>()
                : new Dictionary<string, object?>();
            properties["tenantId"] = new Dictionary<string, object?> { ["type"] = "string", ["description"] = _TenantIdDescription };
            document["properties"] = properties;
            return Serializer.Serialize(document);
        }

        #endregion
    }
}
